    val knowledgeArticles = listOf(
        article("signals-route-types", "Маршрутные и поездные сигналы", "Сигналы", "Как различать назначение сигнала и не терять условия его применения.", listOf("Сначала определяют, каким движением управляет сигнал: поездным, маршрутным или маневровым. Затем читают все одновременно подаваемые признаки — основной огонь, маршрутный указатель и дополнительные показания.", "Одинаковый цвет не всегда означает одинаковое разрешение: значение зависит от типа светофора, места установки и сочетания показаний. При сомнении действие выбирают только по действующей ИСИ и установленному порядку связи."), listOf("светофор", "маршрут", "поездной сигнал", "ИСИ"), movementSource),
        article("signals-shunting", "Маневровые сигналы", "Сигналы", "Что проверить до начала и продолжения маневрового передвижения.", listOf("Разрешение на маневровое передвижение оценивают вместе с маршрутом, стрелками, границей маневров и указаниями руководителя маневров.", "Если сигнал не читается, противоречит полученной команде либо маршрут не ясен, движение не начинают до уточнения установленным способом."), listOf("маневры", "маневровый светофор", "маршрут"), movementSource),
        article("signals-hand", "Ручные сигналы", "Сигналы", "Общие принципы восприятия ручных сигналов днём и ночью.", listOf("Ручной сигнал должен быть однозначно виден адресату. Его значение определяют по способу подачи, применяемому предмету или огню и условиям движения.", "Потеря видимости сигнальщика или неясный сигнал — основание прекратить дальнейшее действие и восстановить связь, а не угадывать команду."), listOf("ручной сигнал", "фонарь", "флаг"), movementSource),
        article("signals-sound-alerts", "Звуковые сигналы и сигналы бдительности", "Сигналы", "Когда звук предупреждает, подтверждает или требует немедленного внимания.", listOf("Звуковые сигналы различаются сочетанием коротких и длинных звуков и применяются в установленных ситуациях. Их нельзя трактовать отдельно от места и обстоятельств подачи.", "После предупредительного сигнала убеждаются, что опасная зона освобождена и команда понята. При отсутствии подтверждения действуют по наиболее безопасному варианту и установленному порядку связи."), listOf("звуковой сигнал", "свисток", "бдительность"), movementSource),
        article("signals-protection-signs", "Сигнальные знаки и ограждение места работ", "Сигналы", "Чем постоянные и временные знаки отличаются от разрешения на движение.", listOf("Сигнальный знак сообщает требование или ориентир, а ограждение защищает конкретное место работ, препятствие либо опасный участок.", "Наличие знака не отменяет сигналы, распоряжения и особые условия маршрута. Временные ограничения проверяют по действующим предупреждениям и местному порядку."), listOf("знак", "ограждение", "место работ", "предупреждение"), movementSource),
        article("signals-head-tail", "Обозначение головы и хвоста поезда", "Сигналы", "Зачем проверяют правильное обозначение состава.", listOf("Обозначение головы и хвоста позволяет участникам движения распознавать направление и полноту состава в разных условиях видимости.", "Конкретный набор огней, фонарей или дисков зависит от вида движения и времени суток; его сверяют с действующей ИСИ. Неисправность обозначения устраняют в установленном порядке до отправления либо докладывают ответственному работнику."), listOf("голова поезда", "хвост поезда", "фонарь", "диск"), movementSource),
        article("brakes-test-overview", "Опробование тормозов: какой вид выбрать", "Тормоза", "Сравнение полного, сокращённого и технологического опробования без подмены одного вида другим.", listOf("Полное опробование подтверждает работу тормозов по составу в полном установленном объёме и является исходной проверкой в предусмотренных Правилами случаях.", "Сокращённое опробование проводят после определённых изменений условий, когда требуется подтвердить целостность тормозной магистрали и действие тормозов в установленной части состава. Оно не заменяет полное опробование, если Правила требуют именно полное.", "Технологическое опробование предусмотрено для грузовых поездов и подтверждает действие тормозов после конкретной технологической операции в ограниченном объёме. Оно не подтверждает состояние хвоста и всего состава, если эти элементы фактически не проверялись.", "Перед проверкой устанавливают причину её проведения, категорию и фактическое состояние поезда, место предыдущего полного опробования и какие соединения или устройства изменялись. По этим данным выбирают вид и объём проверки, а не по удобству или привычному названию."), listOf("виды опробования", "полное", "сокращённое", "технологическое", "тормоза"), brakeSource),
        article("brakes-full-test", "Полное опробование тормозов", "Тормоза", "Проверка целостности магистрали и действия тормозов по всему составу с установленным оформлением результата.", listOf("Полное опробование выполняют в случаях, прямо перечисленных Правилами: в частности, перед отправлением на станциях формирования и оборота, после смены локомотива и в иных ситуациях, где требуется заново подтвердить тормозное обеспечение всего поезда.", "До проверки тормозную сеть заряжают до установленного давления, проверяют её целостность и плотность, а для соответствующего подвижного состава — работу электропневматического тормоза. Конкретная последовательность и выдержки зависят от категории поезда и применяемого оборудования.", "При торможении проверяют срабатывание тормозов у вагонов состава, при отпуске — фактический отпуск. Неисправные или неотпустившие тормоза учитывают и обрабатывают только установленным порядком; визуальный признак на одном вагоне не подтверждает весь поезд.", "По результату определяют фактическое тормозное нажатие и другие требуемые параметры, оформляют справку об обеспечении поезда тормозами и исправном их действии. Машинист сверяет полученные сведения с фактическим составом, массой, осями и установленными нормативами.", "Полное опробование нельзя заменить проверкой локомотива, сокращённым либо технологическим опробованием, если основание требует контроля всего состава."), listOf("полное опробование", "тормоза", "магистраль", "справка", "ВУ-45"), brakeSource),
        article("brakes-short-test", "Сокращённое опробование тормозов", "Тормоза", "Подтверждение целостности магистрали и действия тормозов после предусмотренного Правилами изменения условий.", listOf("Сокращённое опробование выполняют только при наличии установленного основания: например, после прицепки поездного локомотива к составу, если полное опробование ранее выполнено от стационарной установки, после разъединения рукавов или перекрытия концевого крана в составе и в других прямо предусмотренных Правилами случаях.", "До начала называют причину опробования и определяют требуемый объём. Проверяют восстановление целостности тормозной магистрали, прохождение тормозной волны и действие тормозов тех вагонов, которые должны контролироваться для данного основания; когда Правила требуют контроль хвоста, его нельзя заменять проверкой только головной части.", "Команда на торможение и отпуск передаётся установленным способом. Работник у проверяемых вагонов подтверждает фактический прижим и отход колодок или иной предусмотренный признак действия тормоза, а не только изменение давления по прибору локомотива.", "Результат сокращённого опробования сообщают машинисту и оформляют по установленному порядку. При сомнении в целостности магистрали, отсутствии отпуска или неудовлетворительном действии отправление не допускают до устранения причины и выполнения требуемой проверки.", "Сокращённое опробование не является «частичным полным»: его назначение, основание и контролируемая часть состава должны быть определены до начала."), listOf("сокращённое опробование", "частичное опробование", "тормоза", "хвостовой вагон", "целостность магистрали"), brakeSource),
        article("brakes-technological-test", "Технологическое опробование тормозов", "Тормоза", "Ограниченная проверка в грузовом поезде после конкретной технологической операции.", listOf("Технологическое опробование предусмотрено Правилами для грузовых поездов в специально установленных случаях. Его задача — подтвердить действие тормозов после конкретного изменения управления или технологии, когда полное либо сокращённое опробование не требуется.", "Перед началом машинист устанавливает причину проверки и число вагонов, по которым должно быть подтверждено действие тормозов. Проверку выполняют по командам на торможение и отпуск с фактическим контролем срабатывания в предусмотренной Правилами части поезда.", "По приборам локомотива контролируют установленное изменение давления и отсутствие признаков нарушения целостности магистрали. Работник, проверяющий вагоны, докладывает о фактическом торможении и отпуске; одного показания манометра недостаточно для подтверждения механического действия тормозов.", "Если требуемое число тормозов не сработало, отпуск не произошёл либо возникло сомнение в целостности магистрали, технологическое опробование считают неудовлетворительным. Причину устраняют и выполняют тот вид проверки, который требуется по фактической ситуации.", "Технологическое опробование не применяют как сокращённое название любой быстрой проверки и не используют для пассажирского поезда: область его применения в действующих Правилах выделена отдельно для грузовых поездов."), listOf("технологическое опробование", "грузовой поезд", "тормоза", "проверка", "торможение", "отпуск"), brakeSource),
        article("brakes-certificate", "Справка об обеспечении поезда тормозами", "Тормоза", "Какие сведения нужно сопоставить перед отправлением.", listOf("Справка фиксирует расчётные и фактически подтверждённые сведения о тормозном обеспечении и результатах опробования.", "Локомотивная бригада проверяет относящиеся к её обязанностям данные и сопоставляет их с фактическим составом и условиями. Несоответствие не исправляют догадкой: его уточняют с ответственными работниками."), listOf("справка", "тормозное нажатие", "опробование"), brakeSource),
        article("brakes-route-check", "Проверка действия тормозов в пути", "Тормоза", "Как безопасно подтвердить фактическую эффективность торможения.", listOf("Проверку выполняют в месте и режиме, предусмотренных правилами и местными условиями, с учётом профиля, скорости, погоды и состояния пути.", "До проверки выбирают безопасные условия, после — оценивают фактическое снижение скорости и поведение состава. При неудовлетворительном результате продолжают действия только по установленному порядку."), listOf("проверка в пути", "эффективность тормозов", "торможение"), brakeSource),
        article("movement-shunting-command", "Команды при маневровой работе", "ИДП", "Кто передаёт команду и что должно быть понятно до движения.", listOf("До начала передвижения должны быть однозначно понятны руководитель маневров, направление, граница маршрута и способ связи. Машинист повторяет команду, когда это предусмотрено порядком переговоров.", "Противоречивая, неполная или потерянная команда не исполняется до уточнения. Возобновление движения — только после восстановления связи и подтверждения маршрута."), listOf("маневры", "команда", "переговоры", "руководитель маневров"), movementSource),
        article("movement-shunting-speeds", "Скорость при маневрах: как определить ограничение", "ИДП", "Почему нельзя пользоваться одной универсальной цифрой.", listOf("Допустимая скорость зависит от вида передвижения, места, состава, видимости, состояния устройств и дополнительных ограничений. Выбирают минимальное из применимых требований.", "Точную величину сверяют с действующей ИДП, ТРА станции, предупреждениями и полученной командой. Если остановка в пределах видимости не обеспечивается, скорость дополнительно снижают."), listOf("маневры", "скорость", "ТРА", "ограничение"), movementSource),
        article("movement-block-systems", "Системы интервального регулирования", "ИДП", "Общая логика автоблокировки, полуавтоблокировки и движения по особым средствам связи.", listOf("Способ регулирования определяет, какие сигналы и разрешения дают право занять перегон. Нельзя переносить порядок отправления с одной системы на другую.", "При неисправности основных устройств переход выполняют только по зарегистрированному распоряжению и процедуре, предусмотренной для данного участка."), listOf("автоблокировка", "полуавтоблокировка", "перегон", "разрешение"), movementSource),
        article("movement-radio-protocol", "Регламент служебных переговоров", "ИДП", "Как передавать критичную команду без двусмысленности.", listOf("Сообщение содержит адресата, отправителя, место, однозначное действие и относящиеся к нему условия. Критичные сведения повторяют так, чтобы отправитель мог подтвердить правильность приёма.", "Неясность, помехи или расхождение в повторе устраняют до исполнения. Разговор ведут по установленному каналу и фиксируют, когда это требует порядок."), listOf("радиосвязь", "переговоры", "повтор команды", "безопасность движения"), movementSource),
        article("movement-minute-readiness", "Минута готовности", "ИДП", "Контрольный диалог машиниста и помощника перед отправлением поезда.", listOf("Регламент выполняют перед отправлением поезда с железнодорожной станции, с промежуточной станции, а также после остановки на перегоне при разрешающем показании соответствующего светофора — в случаях и порядке, установленных ИДП и местными документами.", "Машинист объявляет «Минуту готовности». Помощник машиниста не ограничивается формальным ответом: он последовательно контролирует относящиеся к данному отправлению условия и докладывает их машинисту установленными формулировками.", "В контроль входят наличие поездных документов и предупреждений, их соответствие поезду и участку; разрешающее показание светофора и правильность маршрута по доступным признакам; отсутствие сигналов остановки; готовность состава и окончание предусмотренных работ.", "Отдельно контролируют давление в тормозной и питательной магистралях. Для грузового поезда выполняют предусмотренные регламентом проверки целостности и плотности тормозной магистрали. Сведения о тормозах и фактическом составе должны соответствовать документам.", "Помощник докладывает также относящиеся к отправлению ограничения, замечания по локомотиву и составу, наличие справки о тормозах и другие пункты, предусмотренные локальным регламентом. Машинист подтверждает восприятие и готовность.", "Если хотя бы один обязательный пункт не подтверждён, показание неясно, документы расходятся с фактическими данными либо получен сигнал остановки, регламент не считается завершённым. Отправление откладывают до устранения несоответствия.", "Дословная форма диалога и дополнительные пункты могут устанавливаться владельцем инфраструктуры и местными документами. В работе применяется утверждённый для участка вариант, а эта карточка служит структурной памяткой."), listOf("минута готовности", "отправление", "помощник машиниста", "переговоры", "тормозная магистраль", "предупреждения"), readinessSource)
