    val safetyArticles = listOf(
        article("safety-tracks-movement", "Передвижение по территории и путям", "Железнодорожная среда", "Безопасный маршрут важнее кратчайшего пути.", listOf("Следуйте утверждённому безопасному маршруту, пользуйтесь переходами и сохраняйте обзор подвижного состава. Не проходите в негабаритных местах и не отвлекайтесь на экран или наушники.", "При изменении обстановки остановитесь в безопасном месте и заново оцените маршрут. Местные схемы прохода и предупреждения обязательны."), listOf("пути", "маршрут", "переход", "подвижной состав"), railwaySafetySource),
        article("safety-standing-stock", "Проход возле стоящего подвижного состава", "Железнодорожная среда", "Стоящий состав может начать движение без дополнительного предупреждения.", listOf("Не пролезайте под вагонами и автосцепками, не переходите путь в местах с ограниченным обзором и не используйте элементы подвижного состава как сокращение маршрута.", "Обход и переход выполняют только способом и на расстоянии, установленными действующими правилами и местной схемой безопасности."), listOf("вагон", "автосцепка", "переход", "габарит"), railwaySafetySource),
        article("safety-locomotive-access", "Подъём и спуск с локомотива", "Безопасная работа", "Три точки опоры и проверка места постановки ноги.", listOf("Перед подъёмом убедитесь, что локомотив закреплён, подножки и поручни исправны и не загрязнены. Поднимайтесь и спускайтесь лицом к локомотиву, сохраняя три точки опоры.", "Не переносите груз, мешающий хвату и обзору; для него применяют предусмотренный способ передачи. Не спрыгивайте и не сходите в сторону соседнего пути без проверки обстановки."), listOf("локомотив", "подножка", "поручень", "три точки опоры"), railwaySafetySource),
        article("safety-external-inspection", "Наружный осмотр локомотива", "Безопасная работа", "Осмотр начинается с ограждения, связи и оценки соседних путей.", listOf("До обхода уточните закрепление локомотива, возможность движения по соседним путям, освещение и безопасный маршрут. Находитесь только там, где сохраняется габарит и видимость.", "К вращающимся, горячим, находящимся под давлением или напряжением частям не приближаются для уточнения признака без предусмотренной подготовки и допуска."), listOf("осмотр", "локомотив", "соседний путь", "габарит"), railwaySafetySource),
        article("safety-contact-wire", "Контактная сеть и неизвестный провод", "Электробезопасность", "Любой оборванный или провисший провод считают находящимся под напряжением.", listOf("Не приближайтесь, не касайтесь провода, связанных с ним предметов и техники. Оградите опасную зону доступным безопасным способом, предупредите людей и немедленно сообщите установленному работнику.", "Выход из опасной зоны выполняют без широких шагов и касания окружающих предметов; дальнейшие действия — только по указанию персонала энергоснабжения и аварийному порядку."), listOf("контактная сеть", "оборванный провод", "шаговое напряжение"), electricalSafetySource),
        article("safety-high-voltage-boundaries", "Границы работ в электроустановках", "Электробезопасность", "Отключённая команда не равна безопасно подготовленному рабочему месту.", listOf("Для допуска требуется выполнить предусмотренные организационные и технические меры: отключение, исключение ошибочной подачи напряжения, проверку отсутствия напряжения, заземление и ограждение — в объёме конкретной работы.", "Самостоятельно расширять рабочее место, снимать ограждения или обходить блокировки нельзя. При сомнении работа прекращается до подтверждения допуска."), listOf("электроустановка", "допуск", "заземление", "блокировка"), electricalSafetySource),
        article("safety-height-roof", "Работа на высоте и крышевом оборудовании", "Безопасная работа", "Доступ на крышу требует одновременно электрической и высотной безопасности.", listOf("Выход на крышу допускается только после подготовки места по правилам электро- и высотных работ, подтверждения допуска, ограждения и применения совместимой системы защиты от падения.", "Погода, обледенение, освещение и состояние опор оцениваются до подъёма и при изменении условий. Наличие страховочной привязи само по себе не делает работу допустимой."), listOf("высота", "крыша", "страховочная система", "контактная сеть"), KnowledgeSource("Приказы Минтруда России №782н, №903н и №860н", "Работа выполняется только подготовленными и допущенными работниками по локальному порядку.")),
        article("safety-ppe-hazard-selection", "Подбор СИЗ по опасности", "СИЗ", "Основное и дополнительное средство определяют по защитной функции, а не по внешнему виду.", listOf("Основное средство обеспечивает требуемую защиту в предусмотренных условиях применения; дополнительное снижает сопутствующий риск и не заменяет основное. Роль одного и того же вида СИЗ зависит от конкретной опасности и технологии.", "Проверяйте маркировку, класс защиты, совместимость, размер и область применения. Перед каждым использованием осматривайте средство; периодические испытания и срок годности сверяйте по паспорту, штампу и учёту работодателя."), listOf("СИЗ", "основные", "дополнительные", "маркировка", "испытание"), ppeSafetySource),
        article("safety-weather-visibility", "Погода, освещение и видимость", "Железнодорожная среда", "Плохая видимость меняет допустимый способ работы.", listOf("Туман, снег, дождь, сильный ветер, жара, мороз и недостаточное освещение увеличивают время реакции и могут скрывать движение, сигналы и препятствия.", "До работы уточните дополнительные меры: освещение, связь, сигнальщика, снижение темпа или прекращение операции. Если условия не позволяют безопасно видеть маршрут и опасности, работу не начинают или приостанавливают."), listOf("погода", "видимость", "освещение", "гололёд"), railwaySafetySource),
        article("safety-fire-smoke", "Дым, запах гари и пожар", "Аварийные ситуации", "Сначала — люди, сообщение и исключение развития опасности.", listOf("При дыме, огне или устойчивом запахе перегрева сообщите установленным способом, оцените угрозу людям и безопасный путь эвакуации. Электрооборудование считают находящимся под напряжением, пока не подтверждено обратное.", "Огнетушитель применяют только если очаг доступен без входа в опасную зону, выбран подходящий тип и сохраняется путь отхода. При росте огня, дыме или риске поражения током прекращают тушение и отходят."), listOf("пожар", "дым", "огнетушитель", "эвакуация"), railwaySafetySource)
